package com.elitedarkkaiser.nubialy.xposed;
import android.app.Application;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.graphics.Color;import android.graphics.drawable.ColorDrawable;import android.view.*;import android.widget.*;import com.elitedarkkaiser.nubialy.*;import java.util.*;import java.util.concurrent.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowContentResolver;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class SettingsRuntimeTest {
 public static class Broker extends ContentProvider {int status=GuardBrokerPolicy.READABLE;boolean bad;public boolean onCreate(){return true;}public Bundle call(String method,String arg,Bundle in){assertEquals(SettingsStyle.METHOD,method);Bundle b=new Bundle();b.putString("nonce",bad?"bad":in.getString("nonce"));b.putInt("version",BuildConfig.VERSION_CODE);b.putInt("status",status);b.putString("permit_id","12345678-1234-4234-8234-123456789abc");b.putLong("deadline_ms",SystemClock.elapsedRealtime()+ClockEnabledPolicy.HEALTH_MS);b.putString("settings_style",SettingsStyle.DEFAULT.with(10,120).encode());return b;}public Cursor query(Uri u,String[]p,String s,String[]a,String o){return null;}public String getType(Uri u){return null;}public Uri insert(Uri u,ContentValues v){return null;}public int update(Uri u,ContentValues v,String s,String[]a){return 0;}public int delete(Uri u,String s,String[]a){return 0;}}
 @Test public void guardedReadSizingNoCompoundingAndBadReplyRestoresNative()throws Exception {Application app=RuntimeEnvironment.getApplication();Broker b=new Broker();var info=new android.content.pm.ProviderInfo();info.authority=GuardBrokerPolicy.AUTHORITY;b.attachInfo(app,info);ShadowContentResolver.registerProviderInternal(GuardBrokerPolicy.AUTHORITY,b);SettingsRuntime r=ReflectionHelpers.callConstructor(SettingsRuntime.class,ReflectionHelpers.ClassParameter.from(Application.class,app));ReflectionHelpers.setField(r,"compatible",true);try{read(r);assertTrue((Boolean)ReflectionHelpers.callInstanceMethod(r,"active"));LinearLayout row=new LinearLayout(app);row.setBackgroundColor(Color.RED);TextView title=new TextView(app);title.setId(android.R.id.title);title.setTextColor(Color.GREEN);title.setTextSize(20);row.addView(title);float nativeSize=title.getTextSize();for(int i=0;i<3;i++)ReflectionHelpers.callInstanceMethod(r,"decorate",ReflectionHelpers.ClassParameter.from(View.class,row));assertEquals(nativeSize*1.2f,title.getTextSize(),.01f);assertTrue(row.getBackground() instanceof SettingsCardDrawable);b.status=GuardBrokerPolicy.BUSY;read(r);assertTrue((Boolean)ReflectionHelpers.callInstanceMethod(r,"active"));b.status=GuardBrokerPolicy.READABLE;b.bad=true;read(r);assertFalse((Boolean)ReflectionHelpers.callInstanceMethod(r,"active"));assertEquals(Color.RED,((ColorDrawable)row.getBackground()).getColor());assertEquals(Color.GREEN,title.getCurrentTextColor());assertEquals(nativeSize,title.getTextSize(),.01f);}finally{ReflectionHelpers.callInstanceMethod(r,"revoke");((Handler)ReflectionHelpers.getField(r,"main")).removeCallbacksAndMessages(null);((ExecutorService)ReflectionHelpers.getField(r,"worker")).shutdownNow();}}
 @Test public void revokeRestoresOriginalHomeListVisibility()throws Exception {Application app=RuntimeEnvironment.getApplication();SettingsRuntime r=ReflectionHelpers.callConstructor(SettingsRuntime.class,ReflectionHelpers.ClassParameter.from(Application.class,app));var type=Class.forName(SettingsRuntime.class.getName()+"$Home");var constructor=type.getDeclaredConstructor(Object.class);constructor.setAccessible(true);Object token=new Object(),home=constructor.newInstance(token);FrameLayout parent=new FrameLayout(app);View nativeList=new View(app);parent.addView(nativeList);nativeList.setVisibility(View.GONE);var custom=new SettingsHomeView(app,SettingsStyle.DEFAULT,List.of(),"Profile",()->{},()->{},()->true);parent.addView(custom);ReflectionHelpers.setField(home,"nativeList",nativeList);ReflectionHelpers.setField(home,"custom",custom);ReflectionHelpers.setField(home,"visibility",View.VISIBLE);Map<Object,Object> homes=ReflectionHelpers.getField(r,"homes");homes.put(token,home);ReflectionHelpers.callInstanceMethod(r,"revoke");assertEquals(View.VISIBLE,nativeList.getVisibility());assertEquals(1,parent.getChildCount());assertSame(nativeList,parent.getChildAt(0));((ExecutorService)ReflectionHelpers.getField(r,"worker")).shutdownNow();}
 @Test public void staleFragmentCallbackCannotMountAnUntrackedHome()throws Exception {Application app=RuntimeEnvironment.getApplication();SettingsRuntime r=ReflectionHelpers.callConstructor(SettingsRuntime.class,ReflectionHelpers.ClassParameter.from(Application.class,app));var type=Class.forName(SettingsRuntime.class.getName()+"$Home");var ctor=type.getDeclaredConstructor(Object.class);ctor.setAccessible(true);Object token=new Object(),home=ctor.newInstance(token);FrameLayout parent=new FrameLayout(app);View list=new View(app);parent.addView(list);var custom=new SettingsHomeView(app,SettingsStyle.DEFAULT,java.util.List.of(),"Profile",()->{},()->{},()->true);var mount=new SettingsHomeMount(list);mount.install(custom);ReflectionHelpers.setField(home,"nativeList",list);ReflectionHelpers.setField(home,"custom",custom);ReflectionHelpers.setField(home,"mount",mount);ReflectionHelpers.setField(r,"style",SettingsStyle.DEFAULT.with(0,1));ReflectionHelpers.setField(r,"deadline",SystemClock.elapsedRealtime()+15000);ReflectionHelpers.callInstanceMethod(r,"applyHome",ReflectionHelpers.ClassParameter.from((Class)type,home),ReflectionHelpers.ClassParameter.from(boolean.class,false));assertEquals(View.VISIBLE,list.getVisibility());assertSame(parent,list.getParent());assertEquals(1,parent.getChildCount());((ExecutorService)ReflectionHelpers.getField(r,"worker")).shutdownNow();}
 private void read(SettingsRuntime r)throws Exception {ReflectionHelpers.callInstanceMethod(r,"read",ReflectionHelpers.ClassParameter.from(java.util.function.Consumer.class,null));((ExecutorService)ReflectionHelpers.getField(r,"worker")).submit(()->{}).get(3,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();}
}
